insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('write-dialogue-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Write Dialogue', 'A play-based activity for strengthening conversation and turn-taking.', 13, '10–15 min', 'Pencil and paper', 'Write a conversation between two characters: correct speech marks, new speaker = new line. Dialogue conventions.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('simple-newspaper-article-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Simple Newspaper Article', 'A hands-on challenge that builds vocabulary and description.', 13, '10–15 min', 'Children''s newspaper or magazine', 'Read a short article from a children''s newspaper or magazine. Non-fiction reading with unfamiliar vocabulary.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('times-tables-i-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Times Tables I', 'An activity that develops classification and categorisation.', 8, '5–10 min', 'Objects for grouping', '3x and 4x tables through grouping activities. Physical arrangement of 4 groups of 3 before abstract recitation.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('fractions-number-line-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Fractions Number Line', 'A hands-on challenge that builds number sense and early maths.', 8, '5–10 min', 'Drawn number line 0 to 1', 'Place ½, ¼, ¾ on a number line. Fraction as a position -- not just a part of a whole.', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('perimeter-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Perimeter', 'A play-based activity for strengthening number sense and early maths.', 8, '5–10 min', 'Ruler, simple rectangle', 'Measure the distance around a rectangle by counting or measuring each side. Perimeter as ''fence around a garden.''', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('food-chains-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Food Chains', 'An activity that develops problem-solving and planning.', 8, '5–10 min', 'Drawing materials', 'Sun → plant → caterpillar → bird → hawk. Draw and label a simple food chain. Energy transfer in ecosystems.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('states-matter-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'States Matter', 'A play-based activity for strengthening reasoning and problem-solving.', 13, '10–15 min', 'Ice, water, kettle (supervised)', 'Solid, liquid, gas. Ice (solid) → water (liquid) → steam (gas). Observe the transitions. Scientific vocabulary.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('compass-directions-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Compass Directions', 'A hands-on challenge that builds working memory.', 8, '5–10 min', 'Compass (or drawn compass rose)', 'N, S, E, W. Use a compass or remember: ''Never Eat Shredded Wheat.'' Navigate outdoors using direction.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('set-own-goals-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Set Own Goals', 'An activity that develops social skills and emotional understanding.', 13, '10–15 min', 'None', 'At the start of a month, set 1 academic, 1 physical, 1 social goal. Review at month end: achieved? Why or why not?', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('adult-help-appropriately-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Adult Help Appropriately', 'A play-based activity for strengthening empathy and perspective-taking.', null, 'Ongoing', 'None', 'Excuse me, I need some help with this when you have a moment.'' Polite adult-addressing in a real context.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('digital-citizenship-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Digital Citizenship', 'A hands-on challenge that builds sharing, fairness and turn-taking.', 13, '10–15 min', 'None', 'What is personal information? What shouldn''t you share online? Age-appropriate internet safety.', 'Children this age can begin to name feelings and see another point of view, with support. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('own-health-appointment-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Own Health Appointment', 'A hands-on challenge that builds independence and self-concept.', null, 'Ongoing', 'None', 'Tell the doctor directly what hurts, where, and for how long. Patient self-reporting builds medical advocacy.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('others-without-envy-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Others Without Envy', 'An activity that develops friendship and cooperative play.', null, 'Ongoing', 'None', 'When a friend or sibling achieves something: genuine celebration without resentment. This is a hard skill -- model it.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('read-facial-expressions-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Read Facial Expressions', 'An activity that develops emotional regulation and vocabulary.', 7, '5–8 min', 'Photos or illustrated cards', 'Look at photos of faces: name the emotion and what might have caused it. Facial decoding with context inference.', 'Children this age can begin to name feelings and see another point of view, with support. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('dissection-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Dissection', 'A play-based activity for strengthening sensory art and texture tolerance.', 18, '15–20 min', 'Vegetable/fruit + blunt knife', 'Dissect a vegetable (broccoli, cabbage) or fruit. Identify parts. Biology observation + vocabulary + fine motor.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('build-bridge-i-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Build Bridge I', 'A hands-on challenge that builds sensory discrimination and integration.', 25, '20–30 min', 'Paper, tape, small weight', 'Build a bridge from paper that holds a weight. Test, identify failure point, redesign. Engineering design cycle.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('night-sky-observation-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Night-Sky Observation', 'An activity that develops sensory discrimination and integration.', 13, '10–15 min', 'None (outdoors at night)', 'Identify the moon phase, Venus, Jupiter if visible. Astronomy: systematic observation of the sky.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('paper-marbling-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Paper Marbling', 'A play-based activity for strengthening water play and sensory exploration.', 18, '15–20 min', 'Oil, water, ink/paint, paper, tray', 'Oil + water in a tray + drops of ink or paint. Swirl and press paper. Transfer the pattern. Surprising and beautiful.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('sound-wave-experiment-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Sound Wave Experiment', 'A hands-on challenge that builds auditory discrimination.', 13, '10–15 min', 'Cling film, bowl, salt', 'Sprinkle salt on a drum surface (stretched cling film over bowl) and speak loudly near it. Watch salt vibrate. Sound = waves.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('personal-hygiene-independence-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Personal Hygiene Independence', 'A hands-on challenge that builds personal hygiene.', 18, '15–20 min', 'Bathroom + toiletries', 'With an adult nearby and checking in periodically (not in the room, but within calling distance) for water temperature and slip safety, let your child shower or bathe independently: wash hair, soap all areas, dry off. Full body hygiene self-management.', 'Doing things for themselves builds the planning and sequencing skills that also support learning. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('laundry-contribution-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Laundry Contribution', 'A play-based activity for strengthening dressing independence.', 13, '10–15 min', 'Laundry items', 'Sort clothes by colour, load them, set the wash. Understanding home management systems.', 'Doing things for themselves builds the planning and sequencing skills that also support learning. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('team-sport-strategy-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Team Sport Strategy', 'A skill-building activity focused on coordination, strength and control.', 25, '20–30 min', 'Team sport equipment', 'Play a team sport with positional roles. ''What''s the strategy? What position are you playing?''', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('swim-breathing-technique-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Swim Breathing Technique', 'A skill-building activity focused on swimming technique.', 18, '15–20 min', 'Swimming pool', 'Always with a trained adult or lifeguard present, practise bilateral breathing in freestyle or any stroke over 25 m. Rhythmic breathing is the most demanding swimming element.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('cycling-route-planning-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Cycling Route Planning', 'A skill-building activity focused on cycling skill and road awareness.', 18, '15–20 min', 'Bicycle', 'Plan and cycle a route from memory: ''We go left at the tree, then right at the gate.'' Navigation + cycling combined.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('gymnastics-sequence-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Gymnastics Sequence', 'A practical challenge that builds jumping power and coordination.', 13, '10–15 min', 'Soft surface', '5-element gymnastics sequence: roll, cartwheel, balance, jump, bridge. Memory + execution + transition.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('jump-rope-i-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Jump Rope I', 'A practical challenge that builds jumping power and coordination.', 13, '10–15 min', 'Two jump ropes', 'Attempt to jump between two turning ropes. Timing two inputs simultaneously = complex visual-motor integration.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('rock-climbing-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Rock Climbing', 'A skill-building activity focused on climbing and whole-body strength.', 25, '20–30 min', 'Bouldering wall or climbing frame', 'Indoor bouldering: read the route, plan the moves, execute. Spatial problem-solving + full-body motor control.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('sprint-technique-i-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Sprint Technique I', 'An activity that develops running speed and endurance.', 8, '5–10 min', 'Open space', 'Run with correct arm action: 90° elbow, drive back (not cross). Technique improvement = physical literacy.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('relay-race-strategy-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Relay Race Strategy', 'A skill-building activity focused on running speed and endurance.', 18, '15–20 min', 'Open space + baton', 'In a relay: ''Where should I stand? When do I reach for the baton?'' Positional thinking in team sport.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('write-story-i-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Write Story I', 'An activity that develops handwriting control.', 25, '20–30 min', 'Pencil and paper', '600-word story: opening, build-up, problem, resolution, ending. Full narrative structure with character development.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('technical-drawing-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Technical Drawing', 'A practical challenge that builds drawing accuracy and detail.', 18, '15–20 min', 'Pencil, ruler, paper', 'Draw the front and side view of a box using a ruler. Technical drawing requires precision + spatial reasoning.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('build-electronic-kit-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Build Electronic Kit', 'An activity that develops construction and spatial precision.', 25, '20–30 min', 'Simple electronic kit', 'Simple electronics kit: traffic light, sound circuit. Read the instructions and build. Engineering literacy.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('engraving-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Engraving', 'A practical challenge that builds fine motor precision and control.', 13, '10–15 min', 'Kitchen foil, cardboard backing, blunt pencil', 'Press designs into kitchen foil with a blunt pencil. The material yields beautifully to pressure -- force calibration.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('detailed-nature-drawing-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Detailed Nature Drawing', 'An activity that develops drawing accuracy and detail.', 18, '15–20 min', 'Drawing materials + specimen', 'Draw an insect or plant in close detail using observation. Scientific illustration requires sustained fine motor and attention.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('architectural-model-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Architectural Model', 'An activity that develops construction and spatial precision.', 25, '20–30 min', 'Cardboard, ruler, scissors, tape', 'Build a model of a room or building from cardboard. Scale and proportion thinking.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('chapter-book-i-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Chapter Book I', 'An activity that develops reading development.', 18, '15–20 min', 'Age-appropriate novel', '200-page novel over 2-3 weeks. Complex plot, multiple characters, sustained memory across sessions.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-argument-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Write Argument', 'An activity that develops written expression.', 18, '15–20 min', 'Pencil and paper', 'Write 4 paragraphs: introduction + claim, argument 1 + evidence, argument 2 + evidence, conclusion. Persuasive structure.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('understand-subtext-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Understand Subtext', 'A practical challenge that builds reading development.', 8, '5–10 min', 'Story extract', 'The character says they''re fine. But what does the author want us to understand they''re really feeling?'' Subtext reading.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('reported-speech-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Reported Speech', 'An activity that develops conversation and presentation.', 8, '5–10 min', 'Any conversation or story', 'Direct vs reported speech format Direct and reported speech -- a significant grammar distinction.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('prefix-suffix-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Prefix Suffix', 'A practical challenge that builds vocabulary depth.', 7, '5–8 min', 'None', 'Un-, re-, pre-, -ful, -less, -ness. How does adding a prefix or suffix change a word''s meaning?', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('research-project-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Research Project', 'An activity that develops reading development.', 25, '20–30 min', 'Multiple reference books', 'Use 3 different sources (books) to research a topic. Compare what each says -- sources may differ. Critical research.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-newspaper-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Write Newspaper', 'An activity that develops written expression.', 25, '20–30 min', 'Pencil, paper, ruler', 'Create a 2-page newspaper: headline story, sport report, weather, comic strip. Multiple text types in one project.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('grammar-clauses-phrases-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Grammar Clauses Phrases', 'An activity that develops written expression.', 8, '5–10 min', 'Printed sentences', 'The dog ran'' is a clause. ''In the garden'' is a phrase. Identify in sentences. Formal grammar awareness.', 'This supports the vocabulary and expression that school will increasingly demand. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('times-tables-ii-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Times Tables II', 'A practical challenge that builds understanding time.', 8, '5–10 min', 'None', '6x, 7x, 8x -- the most difficult tables. Songs, physical arrangements, and chanting all help. Repetition over time.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('long-multiplication-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Long Multiplication', 'A practical challenge that builds number and early mathematical thinking.', 8, '5–10 min', 'Pencil and paper', '23 × 4 using the grid method: 20×4 + 3×4. Breaking a large multiplication into parts -- distributive property.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('bar-graph-creation-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Bar Graph Creation', 'An activity that develops applied literacy thinking.', 13, '10–15 min', 'Pencil, paper, ruler', 'Gather data (family preferences), create a bar graph, and write 3 conclusions. Data literacy with self-generated data.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('earth-solar-system-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Earth Solar System', 'A practical challenge that builds pattern and sequence reasoning.', 8, '5–10 min', 'None', 'Name 8 planets in order from the sun. ''My Very Educated Mother Just Served Us Nachos.'' Scale comparison.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('angles-introduction-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Angles Introduction', 'An activity that develops reasoning, planning and problem-solving.', 7, '5–8 min', 'None', 'Right angle (90°): spot them in the room. Acute and obtuse angles. Geometry vocabulary before protractors.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('biography-reading-discussion-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Biography Reading Discussion', 'A practical challenge that builds applied literacy thinking.', 13, '10–15 min', 'Short biography', 'Read a short biography of a historical figure. ''What challenges did they face? What can we learn from them?''', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('manage-multiple-responsibilities-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Manage Multiple Responsibilities', 'An activity that develops responsibility and contribution.', null, 'Ongoing', 'None', 'Handle 3 concurrent responsibilities: homework, chore, and personal care. Executive function: prioritise and sequence.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('conflict-without-adult-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Conflict Without Adult', 'An activity that develops friendship and social navigation.', null, 'Ongoing', 'None', 'When a peer conflict arises at home, attempt resolution without adult mediation. Debrief after: what did you try?', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('another-s-perspective-fully-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Another''s Perspective Fully', 'A skill-building activity focused on empathy and perspective-taking.', 8, '5–10 min', 'None', 'Tell me the whole story from their point of view -- not yours.'' Full perspective-taking, not just awareness of difference.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('resilience-from-failure-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Resilience from Failure', 'A practical challenge that builds resilience and persistence.', 8, '5–10 min', 'None', 'After a genuine failure: ''What happened? What did you learn? What will you try next time?'' Growth mindset practice.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('manage-screen-time-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Manage Screen Time', 'A skill-building activity focused on emotional regulation and self-awareness.', null, 'Ongoing', 'None', 'Set own screen time limits for a week; track usage; review: ''Did I stick to it? How did it feel?'' Self-regulation of technology.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('understand-misinformation-basics-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Understand Misinformation Basics', 'A practical challenge that builds social understanding and self-regulation.', 8, '5–10 min', 'News item or claim to examine', 'How do you know that''s true? Where did you hear it? Is it always the whole story?'' Media literacy beginning.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('astronomy-observation-journal-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Astronomy Observation Journal', 'A practical challenge that builds sensory discrimination and integration.', 8, '5–10 min', 'Drawing journal + pen', 'Observe and draw the moon every 3 nights for a month. Full lunar cycle observation builds pattern recognition.', 'This supports regulation and focus, which matters more once formal learning begins. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('build-compost-bin-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Build Compost Bin', 'A practical challenge that builds sensory art and material handling.', null, 'Ongoing', 'Container, kitchen waste', 'Start a small compost from kitchen waste. Biology: decomposition, food webs, natural cycles.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('photography-project-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Photography Project', 'A skill-building activity focused on sensory discrimination and integration.', 13, '10–15 min', 'Camera or phone', 'Use a phone or camera: take 10 photos with a chosen theme. Composition awareness + visual literacy.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('fermentation-observation-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Fermentation Observation', 'A practical challenge that builds sensory exploration through water.', 13, '10–15 min', 'Yeast, sugar, warm water, balloon', 'Mix yeast + sugar + warm water and observe bubbles. Microorganism activity as a science phenomenon.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('architecture-observation-walk-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Architecture Observation Walk', 'A skill-building activity focused on sensory discrimination and integration.', 25, '20–30 min', 'None (outdoors)', 'Walk around local buildings: note arches, columns, windows, patterns. Built environment as sensory + aesthetic exploration.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('plan-cook-meal-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Plan Cook Meal', 'A practical challenge that builds simple food preparation.', 38, '30–45 min', 'Ingredients, kitchen tools', 'Choose a recipe, write a shopping list, shop with adult, prepare and serve. Full food chain participation.', 'Children who genuinely contribute at home tend to be more capable and more confident. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('navigate-independently-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Navigate Independently', 'A practical challenge that builds everyday independence and responsibility.', 18, '15–20 min', 'None', 'Walk or cycle a known short route (park and back) independently or with peers -- no adult accompaniment.', 'Children who genuinely contribute at home tend to be more capable and more confident. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('orienteering-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Orienteering', 'A skill-building activity focused on coordination, strength and control.', 25, '20–30 min', 'Hand-drawn map, marked points', 'Follow a simple map to find 5 hidden points in a garden or park. Navigation + map reading + fitness combined.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('batting-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Batting', 'A skill-building activity focused on throwing, catching and aiming accuracy.', 13, '10–15 min', 'Bat and ball', 'Hit a bowled or tossed ball with a bat. Tracking, timing, and swing plane all coordinating.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('swim-backstroke-10m-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Swim Backstroke 10m', 'A practical challenge that builds ball control with the feet.', 18, '15–20 min', 'Swimming pool', 'Backstroke: arms alternating overhead while kicking on back. Different body position = new spatial challenge.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Expect them to want to do it their own way, and let them where you can.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('handstand-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Handstand', 'A skill-building activity focused on ball control with the feet.', 8, '5–10 min', 'Clear wall', 'Kick up to handstand against a wall; hold 3 seconds. Full inversion + weight-bearing through arms.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('sprint-start-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Sprint Start', 'A practical challenge that builds running speed and endurance.', 7, '5–8 min', 'Open space', 'Start from a 3-point stance on signal. Sports start = explosive reaction + acceleration + body position combined.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('hill-climb-y5_3', 'motor'::domain, 'y5_3'::age_band, ': Hill Climb', 'A skill-building activity focused on climbing and whole-body strength.', 13, '10–15 min', 'Bicycle + hill', 'Ride up a gentle slope. Hill cycling requires gear shifting (if applicable), sustained effort, and balance at low speed.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('ball-control-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Ball Control', 'An activity that develops ball control with the feet.', 13, '10–15 min', 'Football or large ball', 'Keep a football in the air using feet, knees, chest. Juggling control is advanced ball mastery.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('variant-freeze-tag-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Variant: Freeze Tag', 'An activity that develops coordination, strength and control.', 13, '10–15 min', 'Open space + players', 'Freeze tag: tag someone, they freeze until unfrozen by another. Spatial awareness + social coordination + motor speed.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('write-story-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Write Story', 'An activity that develops handwriting control.', 25, '20–30 min', 'Pencil and paper', '800-word story with dialogue, descriptive language, and a clear story arc. Word count should be a target, not a ceiling.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('make-zine-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Make Zine', 'An activity that develops precision folding.', 18, '15–20 min', 'A4 paper, scissors, pens', 'Fold a single A4 sheet into an 8-page booklet. Create a mini-magazine: articles, illustrations, cover, contents page.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('scale-drawing-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Scale Drawing', 'A practical challenge that builds drawing accuracy and detail.', 18, '15–20 min', 'Ruler, pencil, graph paper', 'Draw a room to scale (1 cm = 50 cm). Measurement + proportion + spatial representation.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('complex-origami-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Complex Origami', 'An activity that develops precision folding.', 25, '20–30 min', 'Square paper', 'Origami crane or frog: 10+ folds requiring spatial planning and precise crease alignment.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('build-simple-catapult-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Build Simple Catapult', 'A practical challenge that builds construction and spatial precision.', 18, '15–20 min', 'Craft sticks, rubber bands, spoon, tape', 'Craft sticks, rubber bands, plastic spoon. Load, aim, fire. Engineering: force, trajectory, adjustment.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('batik-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Batik', 'A skill-building activity focused on fine motor precision and control.', 25, '20–30 min', 'Candle wax, fabric, dye (food colouring), hot water', 'Apply wax to fabric, dye it, remove wax. The resist print is unpredictable and beautiful. Textile science.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('read-novel-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Read Novel', 'An activity that develops reading development.', 25, '20–30 min', 'Age-appropriate novel', 'A 300-page novel at reading level. Complex character development + sustained reading stamina + literary discussion.', 'This supports the vocabulary and expression that school will increasingly demand. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-book-report-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Write Book Report', 'A practical challenge that builds reading development.', 18, '15–20 min', 'Novel read + pencil and paper', 'Summarise: title, author, main characters, plot, your opinion and why. Non-fiction analytical writing about fiction.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('vocabulary-word-roots-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Vocabulary Word Roots', 'An activity that develops written expression.', 8, '5–10 min', 'None', 'Bio = life, graph = write, tele = far, phon = sound. Root knowledge unlocks unknown word meanings. 5 roots per week.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('debate-i-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Debate I', 'A practical challenge that builds explaining and reasoning aloud.', 18, '15–20 min', 'None', '2-minute opening argument, 1-minute rebuttal, 1-minute closing. Formal debate structure teaches evidence and logic.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-script-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Write Script', 'An activity that develops written expression.', 18, '15–20 min', 'Pencil and paper', 'Write a short play: character list, scene directions, dialogue. Script format is a distinct text type.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('analyse-poem-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Analyse Poem', 'A skill-building activity focused on reading development.', 13, '10–15 min', 'Poem (any short poem)', 'Read a poem: identify the theme, one poetic device, and what line you found most powerful and why.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('edit-own-writing-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Edit Own Writing', 'An activity that develops reading development.', 18, '15–20 min', 'Pencil and paper', 'Write a paragraph, leave it, return next day, and improve it. Editing = reading critically and rewriting, not just correcting.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('persuasive-speech-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Persuasive Speech', 'A skill-building activity focused on conversation and presentation.', 25, '20–30 min', 'None', 'Prepare and deliver a 3-minute persuasive speech on a chosen topic. Introduction, 3 arguments, conclusion, call to action.', 'This supports the vocabulary and expression that school will increasingly demand. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('times-tables-iii-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Times Tables III', 'A skill-building activity focused on number and early mathematical thinking.', 8, '5–10 min', 'Pencil and paper', 'Complete the 12x12 multiplication grid. All tables known reliably: begin exploring patterns (9x = digit sum is 9).', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('long-division-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Long Division', 'An activity that develops classification and logical grouping.', 8, '5–10 min', 'Pencil and paper', '48 ÷ 4 = 12. The conceptual step: how many groups of 4 in 48? Grouping before the algorithm.', 'Understanding at this stage grows from working things out rather than being told the answer. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('decimals-introduction-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Decimals Introduction', 'A skill-building activity focused on reasoning, planning and problem-solving.', 8, '5–10 min', '10 uniform objects + whole', 'Tenths: 0.1, 0.5, 0.7. A decimal is a fraction with 10 in the denominator. Concrete representation with 10 blocks.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('classify-rocks-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Classify Rocks', 'A practical challenge that builds classification and logical grouping.', 13, '10–15 min', 'Rock samples (collected outdoors)', 'Igneous, sedimentary, metamorphic. Find 3 rock types outdoors; identify key features of each.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('history-timeline-project-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'History Timeline Project', 'A skill-building activity focused on understanding time.', 18, '15–20 min', 'Paper, ruler, reference book', 'Create a timeline of a chosen period with 8+ dated events. Chronological thinking + historical knowledge combined.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('logic-puzzles-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Logic Puzzles', 'A skill-building activity focused on spatial reasoning and planning.', 18, '15–20 min', 'Logic puzzle (printable or drawn)', 'A 4x4 logic grid puzzle: deduce which person has which attribute. Systematic elimination = logical reasoning.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('manage-time-project-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Manage Time Project', 'A practical challenge that builds social understanding and self-regulation.', null, 'Ongoing', 'None', 'Given a 5-day project deadline, plan the work across 5 days without being told when to do each step.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('give-constructive-feedback-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Give Constructive Feedback', 'A skill-building activity focused on empathy and perspective-taking.', 8, '5–10 min', 'None', 'I liked… but one thing that could be even better is…'' Structured feedback that''s honest AND kind.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('handle-criticism-gracefully-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Handle Criticism Gracefully', 'A skill-building activity focused on social understanding and self-regulation.', null, 'Ongoing', 'None', 'When given negative feedback: listen fully, ask one question, thank them. Receiving criticism is a learnable skill.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('advocate-someone-else-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Advocate Someone Else', 'An activity that develops friendship and social navigation.', null, 'Ongoing', 'None', 'My friend was upset about what happened. I wanted to say something on their behalf.'' Ally behaviour.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('peer-mediation-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Peer Mediation', 'A skill-building activity focused on friendship and social navigation.', 13, '10–15 min', 'None', 'Help two friends resolve a conflict they''re having. Third-party mediation requires neutrality and listening.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('discuss-moral-dilemma-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Discuss Moral Dilemma', 'A skill-building activity focused on social understanding and self-regulation.', 8, '5–10 min', 'None', 'If you found a wallet full of money with no ID, what would you do?'' Moral reasoning without a single right answer.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('tie-dye-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Tie-Dye', 'An activity that develops sensory discrimination and integration.', 25, '20–30 min', 'White fabric, rubber bands, food dye, water', 'Rubber band a white cloth in patterns, submerge in colour (food dye). Pattern control + colour science + patience.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('candle-making-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Candle-Making', 'An activity that develops sensory exploration through water.', 25, '20–30 min', 'Wax (old candles), wick, container', 'Melt wax, pour into a mould, insert wick. Supervised heat + transformation science + fine motor.', 'This supports regulation and focus, which matters more once formal learning begins. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('build-periscope-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Build Periscope', 'An activity that develops sensory discrimination and integration.', 18, '15–20 min', 'Cardboard tube, two small mirrors, tape', 'Mirrors at 45-degree angles in a tube: see around corners. Optics: angles of reflection.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('kiln-pit-fire-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Kiln Pit Fire', 'A skill-building activity focused on tactile discrimination and refinement.', 38, '30–45 min', 'Air-dry clay, outdoor fire (supervised)', 'Shape clay pots; fire them in a pit fire (with adult supervision). Ancient technology + science of ceramic transformation.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP')
